describe("ESLint#loadFormatter", () => {
	it("loads a custom formatter, sorts results, and exposes formatter context", async () => {
		const cwd = await createTempDir();
		const formatterFilePath = path.join(cwd, "formatter.cjs");
		const plugin = {
			rules: {
				"no-foo": {
					meta: {
						type: "problem",
						docs: { description: "Disallow foo." },
						schema: [],
					},
					create(context) {
						return {
							Identifier(node) {
								if (node.name === "foo") {
									context.report({
										node,
										message: "Do not use foo.",
									});
								}
							},
						};
					},
				},
			},
		};

		await fs.writeFile(
			formatterFilePath,
			`module.exports = function formatter(results, context) {
				return JSON.stringify({
					filePaths: results.map(result => result.filePath),
					cwd: context.cwd,
					maxWarnings: context.maxWarnings,
					rulesMeta: context.rulesMeta
				});
			};\n`,
		);

		const eslint = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: {
				plugins: { example: plugin },
				rules: { "example/no-foo": "error" },
			},
		});
		const first = await eslint.lintText("foo;\n", {
			filePath: "b.js",
		});
		const second = await eslint.lintText("foo;\n", {
			filePath: "a.js",
		});
		const results = [first[0], second[0]];
		const formatter = await eslint.loadFormatter("./formatter.cjs");

		const formatted = JSON.parse(
			formatter.format(results, { maxWarnings: 7 }),
		);

		expect(formatted.filePaths).toEqual([
			path.join(cwd, "a.js"),
			path.join(cwd, "b.js"),
		]);
		expect(formatted.cwd).toBe(cwd);
		expect(formatted.maxWarnings).toBe(7);
		expect(formatted.rulesMeta).toEqual({
			"example/no-foo": plugin.rules["no-foo"].meta,
		});
		expect(results.map(result => path.basename(result.filePath))).toEqual([
			"a.js",
			"b.js",
		]);
	});

	it("loads the default built-in formatter", async () => {
		const cwd = await createTempDir();
		const eslint = createESLint(cwd);
		const formatter = await eslint.loadFormatter();

		expect(typeof formatter.format).toBe("function");
		expect(formatter.format([], { maxWarnings: 0 })).toBe("");
	});

	it("validates formatter names and loading failures", async () => {
		const cwd = await createTempDir();
		const eslint = createESLint(cwd);

		await expect(eslint.loadFormatter(42)).rejects.toThrow(
			"'name' must be a string",
		);
		await expect(eslint.loadFormatter("./missing-formatter.cjs")).rejects.toThrow(
			/There was a problem loading formatter/u,
		);
		await expect(eslint.loadFormatter("table")).rejects.toThrow(
			/The table formatter is no longer part of core ESLint/u,
		);
	});

	it("rejects formatter modules that do not export a function", async () => {
		const cwd = await createTempDir();

		await fs.writeFile(
			path.join(cwd, "invalid-formatter.cjs"),
			"module.exports = { format() { return 'nope'; } };\n",
		);

		const eslint = createESLint(cwd);

		await expect(eslint.loadFormatter("./invalid-formatter.cjs")).rejects.toThrow(
			"Formatter must be a function, but got a object.",
