/**
 * @fileoverview Tests for the ESLint class API.
 */

"use strict";

/* global describe, it, expect, afterEach, jest */

const { existsSync } = require("node:fs");
const fs = require("node:fs/promises");
const os = require("node:os");
const path = require("node:path");
const { pathToFileURL } = require("node:url");

const {
	ESLint,
	shouldUseFlatConfig,
	locateConfigFileToUse,
	calculateWorkerCount,
} = require("../../../lib/eslint/eslint");

const temporaryDirectories = [];

/**
 * Creates a temporary directory that is removed after the current test.
 * @returns {Promise<string>} The directory path.
 */
async function createTempDir() {
	const directory = await fs.mkdtemp(path.join(os.tmpdir(), "eslint-api-"));
	temporaryDirectories.push(directory);
	return directory;
}

/**
 * Creates an ESLint instance with an inline flat config file.
 * @param {string} cwd The working directory.
 * @param {object} [extraOptions] Additional ESLint options.
 * @returns {ESLint} The ESLint instance.
 */
function createESLint(cwd, extraOptions = {}) {
	return new ESLint({
		cwd,
		overrideConfigFile: true,
		overrideConfig: { rules: {} },
		...extraOptions,
	});
}

/**
 * Creates a deprecated rule whose `create()` reports on the Program node.
 * @param {boolean} newFormat Whether to use the newer object form of `deprecated`.
 * @returns {object} A rule definition.
 */
function createDeprecatedRule(newFormat) {
	return {
		meta: {
			type: "problem",
			deprecated: newFormat
				? {
						message: "Use the replacement rule.",
						replacedBy: [
							{
								plugin: { name: "eslint-plugin-example" },
								rule: { name: "replacement" },
							},
							{ rule: { name: "plain-replacement" } },
						],
					}
				: true,
			replacedBy: newFormat ? void 0 : ["plain-replacement"],
			schema: [],
		},
		create(context) {
			return {
				Program(node) {
					context.report({ node, message: "Deprecated rule ran." });
				},
			};
		},
	};
}

afterEach(async () => {
	jest.restoreAllMocks();
	await Promise.all(
		temporaryDirectories
			.splice(0)
			.map(directory =>
				fs.rm(directory, { recursive: true, force: true }),
			),
	);
});

describe("ESLint module entry points", () => {
	it("reports that flat config is used", async () => {
		await expect(shouldUseFlatConfig()).resolves.toBe(true);
	});

	it("exposes static version and flat-config metadata", () => {
		const packageVersion = require("../../../package.json").version;

		expect(ESLint.configType).toBe("flat");
		expect(ESLint.version).toBe(packageVersion);
		expect(ESLint.defaultConfig).toBe(
			require("../../../lib/config/default-config").defaultConfig,
		);
	});

	it("locates a discovered config file and reports its base path", async () => {
		const cwd = await createTempDir();
		const configFilePath = path.join(cwd, "eslint.config.js");

		await fs.writeFile(
			configFilePath,
			"module.exports = [{ rules: {} }];\n",
		);

		await expect(
			locateConfigFileToUse({ configFile: void 0, cwd }),
		).resolves.toEqual({ configFilePath, basePath: cwd });
	});

	it("locates an explicitly supplied config file", async () => {
		const cwd = await createTempDir();
		const configFilePath = path.join(cwd, "custom.config.js");

		await fs.writeFile(
			configFilePath,
			"module.exports = [{ rules: {} }];\n",
		);

		await expect(
			locateConfigFileToUse({ configFile: "custom.config.js", cwd }),
		).resolves.toEqual({ configFilePath, basePath: cwd });
	});

	it("throws when no config file can be found", async () => {
		const cwd = await createTempDir();

		await expect(
			locateConfigFileToUse({ configFile: void 0, cwd }),
		).rejects.toThrow("No ESLint configuration file was found.");
	});
});

describe("ESLint static helpers", () => {
