		expect(astUtils.isLogicalExpression(parseExpression("a && b").node)).toBe(
			true,
		);
		expect(astUtils.isLogicalExpression(parseExpression("a || b").node)).toBe(
			true,
		);
		expect(astUtils.isLogicalExpression(parseExpression("a ?? b").node)).toBe(
			false,
		);
		expect(astUtils.isLogicalExpression(parseExpression("a + b").node)).toBe(
			false,
		);
	});

	test("isCoalesceExpression recognizes ?? only", () => {
		expect(astUtils.isCoalesceExpression(parseExpression("a ?? b").node)).toBe(
			true,
		);
		expect(astUtils.isCoalesceExpression(parseExpression("a || b").node)).toBe(
			false,
		);
	});

	test("isMixedLogicalAndCoalesceExpressions detects mixed pairs", () => {
		const logical = parseExpression("a && b").node;
		const coalesce = parseExpression("a ?? b").node;
		const otherLogical = parseExpression("a || b").node;

		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(logical, coalesce),
		).toBe(true);
		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(coalesce, otherLogical),
		).toBe(true);
		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(logical, otherLogical),
		).toBe(false);
		expect(
