		const outerOptions = { type: "ObjectExpression", parent: importExpression };
		const innerOptions = { type: "ObjectExpression" };

		importExpression.options = outerOptions;

		const withKey = { type: "Identifier", name: "with" };
		const outerProperty = {
			type: "Property",
			computed: false,
			shorthand: false,
			method: false,
			key: withKey,
			value: innerOptions,
			parent: outerOptions,
